// Hazard 1: Leaking Mutable Array Reference
class LeakyScores {
    private int[] scores = {90, 85, 95};
    public int[] getScores() { return scores; } // LEAK!
}
// In caller: scoresObj.getScores()[0] = 0; // Corrupted private memory!

// Safe Fix: Defensive Copying
public int[] getScores() {
    return scores.clone(); // Returns separate copy on heap!
}

