class LeakyGradeBook {
    private int[] grades;

    public LeakyGradeBook(int[] grades) {
        // Bug: Directly storing external reference!
        this.grades = grades;
    }

    // Bug: Leaking internal reference!
    public int[] getGrades() { return grades; }
}

class SecureGradeBook {
    private int[] grades;

    public SecureGradeBook(int[] inputGrades) {
        // Defensive copy on incoming data
        if (inputGrades != null) {
            this.grades = inputGrades.clone();
        } else {
            this.grades = new int[0];
        }
    }

    // Defensive copy on outgoing data
    public int[] getGrades() {
        return grades.clone();
    }

    public int getGradeAt(int index) {
        if (index >= 0 && index < grades.length) {
            return grades[index];
        }
        return -1;
    }
}

public class Main {
    public static void main(String[] args) {
        int[] myGrades = {95, 88, 92};
        SecureGradeBook secure = new SecureGradeBook(myGrades);

        // Attempting to sabotage external array:
        myGrades[0] = 0;
        System.out.println("Secure Grade [0]: " + secure.getGradeAt(0)); // Still 95!

        // Attempting to sabotage via returned array:
        int[] leakedCopy = secure.getGrades();
        leakedCopy[0] = 10;
        System.out.println("After leak attempt: " + secure.getGradeAt(0)); // Still 95!
    }
}

