class GameScores {
    private int[] scores;

    public GameScores(int[] input) {
        this.scores = input != null ? input.clone() : new int[0];
    }

    public int getScoreCount() {
        return scores.length;
    }

    public int getScoreAt(int index) {
        if (index >= 0 && index < scores.length) {
            return scores[index];
        }
        return -1;
    }
}

public class Main {
    public static void main(String[] args) {
        int[] input = {100, 200, 300};
        GameScores gs = new GameScores(input);
        input[0] = 999;
        System.out.println("Score at 0: " + gs.getScoreAt(0));
    }
}

class MemberAccount {
    private String username;
    private int loyaltyPoints;

    public MemberAccount(String name, int points) {
        setUsername(name);
        setLoyaltyPoints(points);
    }

    public void setUsername(String name) {
        if (name != null && !name.trim().isEmpty()) {
            this.username = name.trim();
        } else {
            this.username = "Guest";
        }
    }

    public void setLoyaltyPoints(int points) {
        this.loyaltyPoints = points >= 0 ? points : 0;
    }

    public String getUsername() { return username; }
    public int getLoyaltyPoints() { return loyaltyPoints; }
}

public class Main {
    public static void main(String[] args) {
        MemberAccount acc = new MemberAccount(null, -50);
        System.out.println("Member: " + acc.getUsername() + " | Points: " + acc.getLoyaltyPoints());
    }
}

