class SecureMatrix {
    private int[][] grid;
    private int rows;
    private int cols;

    public SecureMatrix(int rows, int cols) {
        this.rows = rows > 0 ? rows : 1;
        this.cols = cols > 0 ? cols : 1;
        this.grid = new int[this.rows][this.cols];
    }

    public void setCell(int r, int c, int val) {
        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            grid[r][c] = val;
        }
    }

    public int getCell(int r, int c) {
        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            return grid[r][c];
        }
        return -1;
    }
}

public class Main {
    public static void main(String[] args) {
        SecureMatrix m = new SecureMatrix(3, 3);
        m.setCell(1, 1, 99);
        m.setCell(5, 5, 10);
        System.out.println("Center cell: " + m.getCell(1, 1));
    }
}
